  def manager_banner_icon(name, css_class: nil)
    path = ICONS[name.to_s]
    return ''.html_safe unless path

    classes = ['bn-icon-svg', css_class].compact.join(' ')

    raw <<~SVG
      <svg class="#{classes}" fill="none" viewBox="0 0 24 24" stroke-width="1.75" stroke="currentColor" aria-hidden="true">
        <path stroke-linecap="round" stroke-linejoin="round" d="#{path}"/>
      </svg>
    SVG
  end
